 const evidence=[{source_tier:4,authority:finalUrl.hostname,title:htmlText(title),url:finalUrl.href,source_date:b.source_date||null}];let primaryVerified=false;
 if(doi){const primary=`https://doi.org/${doi}`;try{const proof=await fetch(primary,{method:'HEAD',redirect:'follow',headers:{'user-agent':'Shift-Radar/1.0'}});primaryVerified=proof.ok;if(primaryVerified)evidence.unshift({source_tier:2,authority:'Primary research via DOI',title:`Primary study ${doi}`,url:primary,source_date:b.source_date||null,doi})}catch{primaryVerified=false}}
 const dev={url:finalUrl.href,title:htmlText(title).slice(0,500),source_date:b.source_date||null,event_type:'submitted_medical_update',region:b.region||'GLOBAL',regulator:primaryVerified?'Peer-reviewed evidence':'Submitted source',relevance_score:85,urgency_score:70,clinical:true};if(!RELEVANT_RADAR.test(`${dev.title} ${body.slice(0,20000)}`))return j({ok:false,error:'not_relevant_to_shift_radar'},422);
