function publicSourceChange(change){if(!change)return null;const {reviewed_snapshot,...visible}=change;return visible}
async function queue(env){const {results}=await env.DB.prepare(`SELECT * FROM radar_events WHERE status IN ('detected','verified','needs_more_evidence','ready_for_review','approved','hold','publish_failed','published','withdrawn') ORDER BY CASE status WHEN 'ready_for_review' THEN 0 WHEN 'publish_failed' THEN 1 WHEN 'approved' THEN 2 ELSE 3 END,urgency_score DESC,relevance_score DESC,id DESC LIMIT 250`).all();const changes=await pendingSourceChangeMap(env.DB),events=(results||[]).filter(isVisibleRadarReviewRow).map(row=>({...decodeEvent(row),source_change:publicSourceChange(changes.get(row.id))}));return j({ok:true,events,excluded_count:Math.max(0,(results||[]).length-events.length)})}
async function sourceHealth(env){const sources=await loadRadarSources(env.DB),{results=[]}=await env.DB.prepare(`SELECT * FROM radar_scan_runs ORDER BY id DESC LIMIT 500`).all(),now=Date.now(),health=sources.map(source=>{const runs=results.filter(run=>run.source_id===source.id),latest=runs[0],lastSuccess=runs.find(run=>run.status==='completed'),failures=runs.findIndex(run=>run.status==='completed'),consecutiveFailures=failures<0?runs.length:failures,age=lastSuccess?now-Date.parse(lastSuccess.completed_at):Infinity,status=!latest?'never_scanned':latest.status!=='completed'?(consecutiveFailures>=3?'failed':'delayed'):age>45*60*1000?'delayed':'healthy';return{id:source.id,authority:source.authority,url:source.url,tier:Number(source.tier),status,last_attempt:latest?.completed_at||null,last_success:lastSuccess?.completed_at||null,latency_ms:latest?.duration_ms||null,item_count:latest?.item_count||0,new_event_count:latest?.new_event_count||0,consecutive_failures:consecutiveFailures,detail:safe(latest?.detail_json,{})}}),unhealthy=health.filter(x=>x.status!=='healthy'),lastSuccess=health.map(x=>x.last_success).filter(Boolean).sort().at(-1)||null;const coverage=ukCoverage(sources);return j({coverage,ok:unhealthy.length===0&&coverage.complete,status:!coverage.complete?'INCOMPLETE_COVERAGE':health.some(x=>x.status==='failed'||x.status==='never_scanned')?'FAILED':unhealthy.length?'DELAYED':'HEALTHY',last_success:lastSuccess,sources:health})}
const OWNER_ROLES=new Set(['owner','admin']);
function safePublicHttps(value){let u;try{u=new URL(String(value||''))}catch{return null}if(u.protocol!=='https:'||/^(?:localhost|127\.|0\.|10\.|192\.168\.|169\.254\.|172\.(?:1[6-9]|2\d|3[01])\.)/i.test(u.hostname)||u.username||u.password)return null;u.hash='';return u}
