 const edited=await env.DB.prepare(`UPDATE radar_events SET medicine_patch_json=?,content_package_json=?,review_note=?,status='ready_for_review',updated_at=? WHERE id=? AND ${sourceReviewGuardSql()} AND ${retainedReviewGuardSql()}`).bind(JSON.stringify(medicinePatch),JSON.stringify(contentPackage),String(body.note||row.review_note||'').slice(0,2000),iso(),id,...sourceReviewGuardBindings(row),...retainedReviewGuardBindings(row)).run();if(edited.meta?.changes===0)return sourceChangeRequired();
