async function registerFreshness(env,event,patch,pkg){const eventId=event.id,claims=[];for(const f of pkg?.known_facts||[])claims.push({claim:f.claim||f.fact,source:f.source_url||null});if(patch?.latest_update_text)claims.push({claim:patch.latest_update_text,source:null});for(const c of claims.filter(x=>x.claim)){const key=await sha(`${eventId}|${c.claim}`);await env.DB.prepare(`INSERT OR IGNORE INTO radar_freshness_claims(claim_key,event_id,claim_text,source_url,status,next_check_at,created_at,updated_at) SELECT ?,?,?,?,?,?,?,? WHERE EXISTS (SELECT 1 FROM radar_events e WHERE e.id=? AND e.status IN ('approved','publish_failed','published') AND ${sourceReviewGuardSql('e')})`).bind(key,eventId,String(c.claim).slice(0,3000),c.source,'active',new Date(Date.now()+7*86400000).toISOString(),iso(),iso(),event.id,...sourceReviewGuardBindings(event)).run()}}
