  await stillCurrent();
  const site=env.SHIFT_SITE_PUBLISH_ENDPOINT?await post(env.SHIFT_SITE_PUBLISH_ENDPOINT,env.SHIFT_SITE_PUBLISH_TOKEN,sitePayload,'site'):{stored:true};
  await stillCurrent();
  const brain=env.SHIFT_BRAIN_INGEST_ENDPOINT?await post(env.SHIFT_BRAIN_INGEST_ENDPOINT,env.SHIFT_BRAIN_INGEST_TOKEN,safe(job.brain_payload_json,{}),'brain'):{stored:true};
  await stillCurrent();
  const search=env.SHIFT_SEARCH_REFRESH_ENDPOINT&&safe(job.search_payload_json,{}).actions?.length?await post(env.SHIFT_SEARCH_REFRESH_ENDPOINT,env.SHIFT_SEARCH_REFRESH_TOKEN,safe(job.search_payload_json,{}),'search'):{skipped:true};
  await stillCurrent();
  const patch=safe(event.medicine_patch_json,{}),pkg=safe(event.content_package_json,{});
  if(patch.medicine_id)await upsertMedicine(env,patch,event);
  await registerFreshness(env,event,patch,pkg);await radarIntoKnowledge(env,event,patch,pkg);
  const completed=iso();
  const [published]=await env.DB.batch([
   env.DB.prepare(`UPDATE radar_events SET status='published',updated_at=? WHERE id=? AND status IN ('approved','publish_failed') AND ${sourceReviewGuardSql()} AND ${retainedReviewGuardSql()} AND EXISTS (SELECT 1 FROM radar_publication_jobs p WHERE p.id=? AND p.status='running')`).bind(completed,event.id,...sourceReviewGuardBindings(event),...retainedReviewGuardBindings(event),job.id),
   env.DB.prepare(`UPDATE radar_publication_jobs SET status='complete',completed_at=? WHERE id=? AND status='running' AND changes()>0 AND EXISTS (SELECT 1 FROM radar_events e WHERE e.id=radar_publication_jobs.event_id AND e.status='published' AND ${sourceReviewGuardSql('e')})`).bind(completed,job.id,...sourceReviewGuardBindings(event))
  ]);
  if(published.meta?.changes===0)throw Error('source_changed_during_publication');
  const snapshot={...decodeEvent(event),status:'published',updated_at:completed},version=await recordPublicationHistory(env,{eventId:event.id,jobId:job.id,action:'published',destinations,snapshot,actor});
  await audit(env,event.id,'published',actor,{version,destinations,site,brain,search});return j({ok:true,status:'published',version,destinations,site,brain,search});
