  const error=String(e?.message||e),failed=await env.DB.prepare(`UPDATE radar_publication_jobs SET status='failed',error_text=? WHERE id=? AND status='running' AND EXISTS (SELECT 1 FROM radar_events e WHERE e.id=radar_publication_jobs.event_id AND ${sourceReviewGuardSql('e')})`).bind(error,job.id,...sourceReviewGuardBindings(event)).run();
  if(failed.meta?.changes)await env.DB.prepare(`UPDATE radar_events SET status='publish_failed',updated_at=? WHERE id=? AND status IN ('approved','publish_failed') AND ${sourceReviewGuardSql()}`).bind(iso(),event.id,...sourceReviewGuardBindings(event)).run();
  await audit(env,event.id,'publish_failed',actor,{error,job_id:job.id,obsolete_approval:!failed.meta?.changes,external_delivery_requires_review:!failed.meta?.changes});
  return j({ok:false,error:failed.meta?.changes?'publish_failed':'source_changed_review_required',detail:error},failed.meta?.changes?502:409);
